CREATE TABLE audit_events(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), actor_user_id TEXT NOT NULL, action TEXT NOT NULL CHECK(length(action) BETWEEN 1 AND 128), target_type TEXT, target_id TEXT, outcome TEXT NOT NULL CHECK(outcome IN ('success','failure')), detail_json TEXT, created_at TEXT NOT NULL);
CREATE INDEX audit_events_org ON audit_events(org_id, created_at DESC, id DESC);
CREATE INDEX audit_events_action ON audit_events(org_id, action, created_at DESC, id DESC);
CREATE TABLE notifications(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL, scope TEXT NOT NULL CHECK(scope IN ('personal','org')), category TEXT NOT NULL, title TEXT NOT NULL CHECK(length(title) BETWEEN 1 AND 200), body TEXT CHECK(body IS NULL OR length(body) <= 500), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','awaiting_action','completed','failed','cancelled')), progress_percent REAL CHECK(progress_percent IS NULL OR (progress_percent >= 0 AND progress_percent <= 100)), detail_json TEXT, dedup_key TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, dismissed_at TEXT, UNIQUE(org_id, dedup_key));
CREATE INDEX notifications_inbox ON notifications(org_id, dismissed_at, created_at DESC, id DESC);
